const cand = $('Enrichment Batch').item.json;
const resp = $json;
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,10}/g;
const bad = /(\.png|\.jpg|\.jpeg|\.gif|\.svg|\.webp|\.css|\.js)$|example\.com|sentry|wixpress|godaddy|schema\.org|@2x|no-?reply|\.wixsite\.|placeholder/i;
const extract = (h) => [...new Set((h.match(emailRe) || []).map(e => e.toLowerCase()))].filter(e => !bad.test(e));
const originMatch = String(cand.website || '').match(/^https?:\/\/[^\/]+/);
const origin = originMatch ? originMatch[0] : null;
const domain = origin ? origin.replace(/^https?:\/\//, '').replace(/^www\./, '') : null;
const resolveUrl = (href) => { if (!href) return null; if (/^https?:\/\//i.test(href)) return href; if (href.startsWith('//')) return 'https:' + href; if (!origin) return null; if (href.startsWith('/')) return origin + href; return origin + '/' + href; };
const toText = (h) => h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
let error = null, emails = [], socials = {}, contactUrl = null, title = null, metaDesc = null, ogDesc = null, aboutUrl = null, pageText = null;
const html = typeof resp.data === 'string' ? resp.data : null;
if (resp.error) { error = String(resp.error.message ?? resp.error); } else if (!html) { error = 'empty or non-text response'; }
if (html) {
  pageText = toText(html).slice(0, 3000);
  emails = extract(html).slice(0, 10);
  const lk = html.match(/https?:\/\/(?:[a-z]{2,3}\.)?linkedin\.com\/(?:company|in)\/[A-Za-z0-9._%\-]+/i); if (lk) socials.linkedin = lk[0];
  const fb = html.match(/https?:\/\/(?:www\.)?facebook\.com\/(?!sharer|share|plugins)[A-Za-z0-9.\-_]{3,}/i); if (fb) socials.facebook = fb[0];
  const ig = html.match(/https?:\/\/(?:www\.)?instagram\.com\/(?!p\/)[A-Za-z0-9._\-]{3,}/i); if (ig) socials.instagram = ig[0];
  const links = [...html.matchAll(/href=["']([^"']*(?:contact|get-in-touch|enquir)[^"']*)["']/gi)].map(m => m[1]).filter(l => !/mailto:|javascript:|\.pdf$|#/i.test(l));
  const pick = links.find(l => /contact|get-in-touch|enquir/i.test(l)) ?? links[0];
  contactUrl = resolveUrl(pick);
  const abLinks = [...html.matchAll(/href=["']([^"']*(?:about|team|our-story|who-we-are|meet-the)[^"']*)["']/gi)].map(m => m[1]).filter(l => !/mailto:|javascript:|\.pdf$|#/i.test(l));
  aboutUrl = resolveUrl(abLinks[0]);
  const t = html.match(/<title[^>]*>\s*([^<]{3,200}?)\s*<\/title>/i); if (t) title = t[1].replace(/\s+/g, ' ').trim();
  const md = html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']{10,500})["']/i) || html.match(/<meta[^>]+content=["']([^"']{10,500})["'][^>]*name=["']description["']/i); if (md) metaDesc = md[1].trim();
  const od = html.match(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']{10,500})["']/i) || html.match(/<meta[^>]+content=["']([^"']{10,500})["'][^>]*property=["']og:description["']/i); if (od) ogDesc = od[1].trim();
}
const pref = (list) => list.find(e => /^(info|contact|admin|hello|enquiries|enquiry|office|sales|reception|bookings)@/.test(e)) || (domain ? list.find(e => e.endsWith('@' + domain)) : null) || list[0] || null;
const need_browser = (!!error || emails.length === 0);
const description = ogDesc || metaDesc || null;
return { json: { candidate_id: cand.id, website: cand.website, email: pref(emails), emails, socials, contact_url: contactUrl, need_contact_page: (!!contactUrl && !error), need_browser, error, title, description, about_url: aboutUrl, need_about: (!!aboutUrl && !error), people: [], page_text: pageText } };

