const base = $('Has About Page?').item.json;
const resp = $json;
const html = typeof resp.data === 'string' ? resp.data : null;
let people = [];
let description = base.description ?? null;
let aboutText = null;
if (html) {
  const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
  const ROLE = '(Owner|Co-?Owner|Director|Managing Director|General Manager|Office Manager|Property Manager|Practice Manager|Principal|Founder|Co-?Founder|CEO|Manager)';
  const nameFirst = new RegExp('([A-Z][a-z]{1,15} [A-Z][a-z]{1,20}) ?[,\\-|:]? ?' + ROLE + '\\b', 'g');
  const roleFirst = new RegExp(ROLE + ' ?[,\\-|:]? ?([A-Z][a-z]{1,15} [A-Z][a-z]{1,20})', 'g');
  const seen = {};
  let m;
  while ((m = nameFirst.exec(text)) !== null && people.length < 6) { if (!seen[m[1]]) { seen[m[1]] = 1; people.push({ name: m[1], role: m[2] }); } }
  while ((m = roleFirst.exec(text)) !== null && people.length < 6) { if (!seen[m[2]]) { seen[m[2]] = 1; people.push({ name: m[2], role: m[1] }); } }
  if (!description) { const od = html.match(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']{10,500})["']/i) || html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']{10,500})["']/i); if (od) description = od[1].trim(); }
  aboutText = text.slice(0, 600).trim();
}
return { json: Object.assign({}, base, { description, people, about_text: aboutText }) };
